{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Integrative care in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="Whole-person care blending evidence, nutrition, lifestyle, and heart. Meet {{PRACTITIONER_NAME}}, {{CREDENTIALS}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="aura">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <button id="nav-toggle" aria-label="Toggle navigation">☰</button>
      <nav id="nav" class="nav">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Concerns</a>
        <a href="/approach.html">Method</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">Our Story</a>
        <a href="/book.html">Schedule</a>
        <a href="/contact.html">Reach Out</a>
      </nav>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Care that considers your whole story — not just symptoms.</h1>
          <p class="lead">Integrative, evidence-informed care with personalized plans that honor body, mind, and rhythm. Meet {{PRACTITIONER_NAME}}, {{CREDENTIALS}}, welcoming curious patients in {{CITY}}, {{STATE}}.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet the clinician</a>
          </div>
        </div>
        <div class="hero-card">
          <div class="card-inner">
            <p class="micro">Quick line</p>
            <h3>New patient intensive</h3>
            <p>90-minute first visit with focused education, testing review options, and a tailored plan to get started.</p>
            <p class="muted">Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
            <a class="btn small" href="/book.html">Book a visit</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Social proof -->
    <section class="social-proof wrap">
      <h2>People feel heard — and steady</h2>
      <div class="proof-grid">
        <blockquote>"Finally someone who connected the dots between sleep, digestion, and stress with a clear plan."</blockquote>
        <blockquote>"Gentle, smart, and practical — the follow-ups keep me accountable."</blockquote>
        <div class="badge">4.9 ★ average patient feedback</div>
      </div>
    </section>

    <!-- Benefits -->
    <section class="benefits" id="benefits">
      <div class="wrap">
        <h2>How integrative care helps you</h2>
        <p class="intro">No magic promises — just thoughtful education and stepwise plans that respect your life.</p>
        <ul class="benefit-list">
          <li>
            <h3>Personalized plans</h3>
            <p>Nutrition, movement, sleep strategies and selective testing explained in plain language.</p>
          </li>
          <li>
            <h3>Root-focused thinking</h3>
            <p>We look for upstream contributors rather than only masking symptoms.</p>
          </li>
          <li>
            <h3>Collaborative care</h3>
            <p>We work with your existing providers, offering education and coordinated options.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- Process -->
    <section class="process wrap">
      <h2>Our approach — clear steps, educational at every turn</h2>
      <div class="steps">
        <div class="step">
          <h4>1. Intake & story</h4>
          <p>We spend time understanding your history, priorities, and patterns.</p>
        </div>
        <div class="step">
          <h4>2. Shared plan</h4>
          <p>A practical, prioritized plan with lifestyle steps and optional targeted labs (education provided).</p>
        </div>
        <div class="step">
          <h4>3. Follow-ups</h4>
          <p>Short check-ins to refine, troubleshoot, and support habit changes.</p>
        </div>
        <div class="step">
          <h4>4. Optional testing</h4>
          <p>Labs are discussed as tools — never mandatory. We explain what they may show and how results guide care.</p>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq wrap" id="faq">
      <h2>Frequently asked</h2>
      <details>
        <summary>Do you offer guaranteed cures?</summary>
        <p>No. We focus on education and realistic plans that support whole-person wellness; individual results vary.</p>
      </details>
      <details>
        <summary>Will I need lots of tests?</summary>
        <p>Tests are optional and recommended only when they will change the plan or clarify a question.</p>
      </details>
      <details>
        <summary>Is this covered by insurance?</summary>
        <p>Billing policies vary; contact us at {{PHONE}} or {{EMAIL}} for details.</p>
      </details>
    </section>

    <!-- Lead magnet -->
    <section class="lead-magnet wrap">
      <div class="magnet-grid">
        <div>
          <h2>Free guide: Small shifts for steady energy</h2>
          <p>Sign up to receive a short guide with practical habits you can try this week.</p>
        </div>
        <form id="lead-form">
          <label for="email">Email</label>
          <input id="lead-email" name="email" type="email" placeholder="you@example.com" required>
          <button class="btn primary" type="submit">Send me the guide</button>
          <p class="muted small">We respect your privacy. No spam.</p>
        </form>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta wrap">
      <h2>Ready to get curious about feeling better?</h2>
      <p>Start with an intensive visit to map priorities and sensible first steps.</p>
      <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="col">
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <div class="col">
        <p>Phone: {{PHONE}}</p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div class="col">
        <nav>
          <a href="/about.html">About</a>
          <a href="/contact.html">Contact</a>
          <a href="/privacy.html">Privacy</a>
        </nav>
      </div>
    </div>
  </footer>

</body>
</html>"} 
