{"path":"assets/css/styles.css","content":"/* Aura editorial – playful premium */
:root{
  --bg:#fffaf6;
  --muted:#6b6b6b;
  --accent:#6b8f6b;
  --accent-2:#8aa6d8;
  --ink:#162029;
  --card:#ffffffee;
  --radius:12px;
  --max:1100px;
  font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
body.aura{background:linear-gradient(180deg,var(--bg),#f7fbff);color:var(--ink);margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:24px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(90deg,rgba(255,255,255,0.7),rgba(250,250,250,0.6));border-bottom:1px solid rgba(0,0,0,0.04);}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--ink);text-decoration:none;font-size:1.125rem}
#nav{margin-left:auto;display:flex;gap:14px}
#nav a{color:var(--ink);text-decoration:none;padding:8px;border-radius:8px}
#nav a:hover{background:rgba(107,143,107,0.07)}
.cta{margin-left:12px;padding:8px 12px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;border-radius:10px;text-decoration:none}
#nav-toggle{display:none;background:none;border:0;font-size:20px}
.hero{padding:48px 0;background-size:600px; background-repeat:no-repeat; background-position:80% 10%;}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start}
.hero-copy h1{font-size:2.1rem;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-card{align-self:start}
.card-inner{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 6px 20px rgba(24,32,32,0.06)}
.micro{font-size:12px;color:var(--accent-2)}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;color:var(--ink);border:1px solid rgba(0,0,0,0.06);}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;border:0}
.btn.ghost{background:transparent}
.btn.small{padding:8px 10px;font-size:14px}
.btn.large{padding:14px 20px;font-size:18px}
.social-proof{padding:36px 0}
.proof-grid{display:grid;grid-template-columns:1fr 1fr 180px;gap:18px;align-items:center}
.proof-grid blockquote{background:white;padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(24,32,32,0.05);margin:0;color:var(--muted)}
.badge{background:linear-gradient(90deg,#fff 0%,#f3fff3 100%);padding:12px;border-radius:12px;text-align:center;font-weight:700}
.benefits{padding:24px 0}
.benefit-list{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;list-style:none;padding:0;margin:18px 0 0}
.benefit-list li{background:var(--card);padding:18px;border-radius:12px}
.process{background:linear-gradient(180deg,rgba(138,166,216,0.06),transparent);padding:28px 0;border-radius:12px}
.steps{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.step{background:white;padding:14px;border-radius:12px}
.faq details{background:white;padding:12px;border-radius:10px;margin:10px 0}
.lead-magnet{padding:28px 0}
.magnet-grid{display:grid;grid-template-columns:1fr 320px;gap:18px;align-items:center}
#lead-form{display:flex;flex-direction:column;gap:8px}
#lead-form input{padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.08)}
.final-cta{padding:28px 0;text-align:center}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:24px 0;margin-top:36px}
.site-footer .wrap{display:flex;gap:12px}
.site-footer .col{flex:1}
.muted{color:var(--muted)}
.small{font-size:13px}
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .magnet-grid{grid-template-columns:1fr}
  .proof-grid{grid-template-columns:1fr}
  #nav{position:fixed;right:12px;top:64px;display:none;flex-direction:column;background:rgba(255,255,255,0.98);padding:12px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.08)}
  #nav.show{display:flex}
  #nav-toggle{display:block;margin-left:auto}
}
/* Decorative accent */
.hero:before{content:"";position:absolute;left:0;right:0;top:0;height:150px;background:radial-gradient(circle at 10% 20%, rgba(107,143,107,0.08), transparent 30%);pointer-events:none}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  var btn=document.getElementById('nav-toggle');
  var nav=document.getElementById('nav');
  if(btn&&nav){btn.addEventListener('click',function(){nav.classList.toggle('show');});}

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var target=document.querySelector(this.getAttribute('href'));
      if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});}    
    });
  });

  // Lead magnet form
  var form=document.getElementById('lead-form');
  if(form){
    form.addEventListener('submit',function(e){
      e.preventDefault();
      var email=document.getElementById('lead-email').value;
      if(!email) return;
      // Simulate async signup
      var btn=form.querySelector('button');
      var original=btn.innerText;
      btn.disabled=true;btn.innerText='Sending...';
      setTimeout(function(){
        form.innerHTML='<p class="small">Thanks! Check your inbox for "Small shifts for steady energy" — sent to '+(email||'your email')+'.</p>';
      },900);
    });
  }
});"} 
